Algoritmo Negativo
  Dimension imagen[4, 4] Como Entero;
  Para f <- 0 Hasta 3 Hacer
    Para c <- 0 Hasta 3 Hacer
      Leer imagen[f, c];
    FinPara
  FinPara
  Para f <- 0 Hasta 3 Hacer
    Definir linea Como Cadena <- "";
    Para c <- 0 Hasta 3 Hacer
      linea <- linea + ConvertirATexto(1 - imagen[f, c]);
    FinPara
    Escribir linea;
  FinPara
FinAlgoritmo
